API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(tls_proxy, "TLS Termination & Routing Proxy", "Kong / Nginx", "Handles incoming HTTPS traffic, performs TLS termination, and routes requests to appropriate backend services.")
    Component(auth_filter, "Authentication & Authorization Filter", "Kong / Nginx Security Filter / OAuth2/OIDC", "Validates OAuth2/OIDC tokens by communicating with the Enterprise Identity Provider.")
    Component(rate_limit, "Rate Limiting & Threat Protection Module", "Kong / Nginx Module", "Protects the system by enforcing rate limits and mitigating security threats.")
    Component(fhir_filter, "FHIR Protocol & Audit Translation Filter", "Kong / Nginx Custom Filter", "Translates and processes HL7 FHIR APIs for external interoperability and audit logging.")
}

Rel(tls_proxy, auth_filter, "Passes incoming requests for token validation", "")
Rel(auth_filter, rate_limit, "Forwards authenticated requests for traffic management", "")
Rel(rate_limit, fhir_filter, "Routes valid requests for protocol translation or internal routing", "")

@enduml

Async Message Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Async Message Broker", "Async Message Broker") {
    Component("Event Ingestion & Routing Engine", "Event Ingestion & Routing Engine", "Apache Kafka", "Handles incoming domain events and routes them to appropriate topics.")
    Component("Schema Registry", "Schema Registry", "Kafka Schema Registry", "Manages and validates event schemas to ensure data consistency.")
    Component("Consumer Offset Manager", "Consumer Offset Manager", "Apache Kafka", "Tracks message consumption progress for consumers.")
    Component("Access Control & Audit Interceptor", "Access Control & Audit Interceptor", "Kafka ACLs / Java", "Persists broker audit logs and ACL metadata while enforcing security policies.")
    Component("Replication & Mirroring Agent (MirrorMaker 2)", "Replication & Mirroring Agent (MirrorMaker 2)", "Kafka MirrorMaker 2", "Handles cross-region replication and mirroring of event streams.")
}

System_Ext("PostgreSQL Primary DB", "PostgreSQL Primary DB", "Multi-region active-active with AES-256 encryption.")

Rel("Access Control & Audit Interceptor", "PostgreSQL Primary DB", "Persists broker audit logs and ACL metadata", "JDBC / TLS")

@enduml

PostgreSQL Primary DB.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(PostgreSQL_Primary_DB, "PostgreSQL Primary DB") {
    Component(Relational_Storage_Engine, "Relational Storage Engine", "PostgreSQL 15+ with Citus", "Core relational storage engine with horizontal scaling capabilities.")
    Component(Connection_Pooler, "Connection Pooler", "PgBouncer", "Connection pooler for handling high-volume client traffic.")
    Component(Audit___Compliance_Logger, "Audit & Compliance Logger", "pgAudit", "Extension for comprehensive DDL/DML auditing to satisfy HIPAA/GDPR.")
    Component(Backup___Archival_Daemon, "Backup & Archival Daemon", "Barman", "Backup and recovery daemon for continuous WAL archiving.")
}

Rel(Connection_Pooler, Relational_Storage_Engine, "Pooled connections via TCP/IP.")
Rel(Relational_Storage_Engine, Backup___Archival_Daemon, "WAL streaming over TLS.")
@enduml
